const m = $input.first().json.body || $input.first().json;
const system = "<private instructions: kept out of this repository>";
const user = "Meta lead form. Name: " + (m.name || m.full_name || "?") + ", " + (m.company || "") + ", " + (m.country || m.city || "") + "\nAd: " + (m.ad_name || m.campaign || "?") + "\nForm answers: " + JSON.stringify(m.answers || m.message || m);
const schema = {"type":"object","additionalProperties":false,"required":["brand","wants","urgency","suggested_reply","next_step"],"properties":{"brand":{"type":"string"},"wants":{"type":"string"},"urgency":{"type":"string","enum":["urgent","high","normal","low"]},"suggested_reply":{"type":"string"},"next_step":{"type":"string"}}};
return [{ json: { input: m, 
  grok: { model: "grok-4.7", temperature: 0, messages: [{ role: "system", content: system }, { role: "user", content: user }],
    response_format: { type: "json_schema", json_schema: { name: "answer", strict: true, schema } } },
  claude: { model: "claude-opus-5-5", max_tokens: 3000, output_config: { effort: "low", format: { type: "json_schema", schema } },
    system, messages: [{ role: "user", content: user }] } } }];

const j = $input.first().json;
let text, ai;
if (j.choices) { text = j.choices[0].message.content; ai = "Grok 4.7 (xAI)"; }
else { if (j.stop_reason === "refusal") throw new Error("Claude declined"); text = (j.content || []).filter(b => b.type === "text").map(b => b.text).join(""); ai = "Claude Opus 5.5 (backup)"; }
let a; try { a = JSON.parse(text); } catch (e) { throw new Error("AI answer was not valid JSON"); }
const input = $('Prepare the question').first().json.input;
const values = {
  "__drop575": input.company || "", "text_mm9cnab6": input.country || "", "color_mm9c3svj": a.brand, "text_mm9c5emj": String(a.wants).slice(0, 250),
  "__drop576": "new_meta_lead (" + ai + ")", "color_mm9cpd1j": a.urgency, "color_mm9c54h3": "telecaller",
  "__drop579": { text: a.suggested_reply }, "text_mm9cv10y": { text: a.next_step } };
return [{ json: { ai, draft: a, monday: { query: "mutation ($b: ID!, $n: String!, $v: JSON!) { create_item(board_id: $b, item_name: $n, column_values: $v, create_labels_if_missing: true) { id } }",
    variables: { b: "<monday-board-id>", n: (input.name || input.full_name || "Meta lead") + " (Meta ad)", v: JSON.stringify(Object.fromEntries(Object.entries(values).filter(([k]) => !k.startsWith("__drop")).map(([k, v]) => [k, ["color_mm9cpd1j","color_mm9c1s94","color_mm9c54h3","color_mm9c38n","color_mm9c3svj","color_mm9ck3pv"].includes(k) && typeof v !== "object" ? { label: String(v).replace(/^./, (x) => x.toUpperCase()) } : v]))) } } } }];
